[400] = { en = "Tools for Steelgrill", tier = 1,
  t = "Gereedschap voor Steelgrill",
  d = "Beldin Steelgrill heeft hier een werkplaats, en hij is de beste monteur voor belegeringsmachines die er is! Maar hij is niet zuinig op zijn gereedschap. Ik zweer het: hij maakt bijna meer sleutels kapot dan wij kunnen leveren!$B$BWe hebben net zijn laatste bestelling klaar. Als jij die naar hem brengt, krijg je vast iets terug voor de moeite.$B$BZijn werkplaats, Steelgrill's Depot, ligt net ten noordoosten van Kharanos. Veel ervaren piloten van belegeringsmachines komen daar, dus houd je oren open voor werk als je er bent.",
  o = "Breng Steelgrill's Tools naar Beldin Steelgrill.",
  c = "Heb je mijn gereedschap? Goed gedaan, $gjongen:meid;, goed gedaan! Een uur geleden is mijn laatste ratel kapotgegaan, en die heb ik nodig om de machine van Pilot Stonegear te repareren. Je hebt er goed aan gedaan om dat gereedschap hierheen te sjouwen, $n.$B$BHier, neem deze munten voor je hulp.",
  p = "Hm? Je ziet er wat jong uit voor een piloot van een belegeringsmachine. Maar dat maakt niet uit... Moet er iets gerepareerd worden?$B$BNou, neem een nummertje en ga lekker zitten. Ik werk nu aan een paar machines en heb de komende dagen geen tijd voor nog een klus.$B$BOf kwam je voor iets anders...?",
  g = { {"gereedschap", "tools"}, {"werkplaats", "workshop"}, {"monteur", "mechanic"},
        {"belegeringsmachines", "siege engines"}, {"zuinig", "careful (with things), thrifty"},
        {"zweer", "swear"}, {"kapot", "broken"}, {"leveren", "to supply, deliver"}, {"bestelling", "order"},
        {"ervaren", "experienced"}, {"repareren", "to repair"}, {"sjouwen", "to lug, haul"},
        {"munten", "coins"}, {"klus", "job, task"} },
},

[2160] = { en = "Supplies to Tannok", tier = 1,
  t = "Voorraad voor Tannok",
  d = "Hé! Jij ziet eruit als een stoere avonturier. Ga je door de bergpas? Kun je dan een pakket naar de herberg in Kharanos brengen?$b$bJe wilde toch even stoppen bij de herberg? Als je door de pas komt, wil je daar zeker even uitrusten.$b$bHoe dan ook, breng dit naar Tannok Frosthammer. Hij is de assistent van de herbergier. Ik kom zelf niet door de pas, en het duurt nog dagen voordat er een escorte van Mountaineers komt!",
  o = "Breng de Crate of Inn Supplies naar Tannok Frosthammer in Kharanos.",
  c = "Ah, eindelijk, de voorraad van Hands! Ik begon me zorgen te maken. We horen bijna niets meer uit Anvilmar sinds de troggs de pas hebben ingenomen.$b$bBedankt dat je dit gebracht hebt, $n. En voel je thuis, alsjeblieft. Je bent vast moe na je reis.",
  p = "Hallo daar! Kom binnen, ga lekker bij het vuur zitten en warm je op met een kroes bier.",
  g = { {"voorraad", "supplies, stock"}, {"stoere", "tough, hearty"}, {"pakket", "package"},
        {"herberg", "inn"}, {"uitrusten", "to rest"}, {"herbergier", "innkeeper"}, {"eindelijk", "at last"},
        {"voel je thuis", "make yourself at home"}, {"moe", "tired"}, {"reis", "journey"}, {"kroes", "mug, flagon"} },
},

[310] = { en = "Bitter Rivals", tier = 1,
  t = "Bittere rivalen",
  d = "Ik moet toegeven: die Thunderbrews maken goede drankjes. Maar ze moeten leren dat hun bier niet het enige goede bier is! Misschien kun jij me helpen om ze dat te leren...$B$BHier, neem dit vat Barleybrew Scalder. Sluip naar de kelder van de Thunderbrew Distillery in Kharanos en ruil het om met een van hun vaten Thunder Ale. Dan zien we wel of hun klanten mijn bier lekkerder vinden!$B$BEn als de vaten bewaakt worden, moet je de bewaker misschien afleiden...",
  o = "Vervang in de kelder van de Thunderbrew Distillery in Kharanos een vat Thunder Ale door een Barrel of Barleybrew Scalder.",
  c = "Je zet het vat Barleybrew Scalder van Marleth snel tussen de vaten van Thunderbrew.",
  p = "De datum op dit vat laat zien dat het binnenkort wordt aangeslagen.",
  g = { {"bittere", "bitter"}, {"rivalen", "rivals"}, {"het enige", "the only"}, {"leren", "to learn / to teach"},
        {"sluip", "sneak"}, {"ruil ... om", "swap (omruilen)"}, {"klanten", "customers"}, {"lekkerder", "tastier"},
        {"bewaker", "guard"}, {"afleiden", "to distract"}, {"vervang", "replace"}, {"binnenkort", "soon"},
        {"aangeslagen", "tapped (a barrel)"} },
},

[317] = { en = "Stocking Jetsteam", tier = 1,
  t = "Voorraad voor Jetsteam",
  d = "Ik ga bijna op missie voor de Siege Brigade. Het wordt een lange tocht, en ik moet Jetsteam vullen met voorraad voor een maand. Kun jij voor mij gaan jagen terwijl Steelgrill aan mijn tank werkt?$B$BIk heb vacht nodig om op te slapen, en zwijnenvlees om te eten. Vlees krijg je van zwijnen en vacht van beren... Ze leven allebei op de sneeuwvlaktes ten zuiden van de Grizzled Den.",
  o = "Verzamel 4 Chunks of Boar Meat en 2 Thick Bear Furs, en breng ze naar Pilot Bellowfiz bij Steelgrill's Depot.",
  c = "Bij Magni's baard, wat heb jij veel gejaagd!! Dank je wel, $n.",
  p = "De voorbereidingen gaan goed. Hoe gaat het met de jacht?",
  g = { {"missie", "mission"}, {"tocht", "trip, expedition"}, {"vullen", "to fill, stock"}, {"maand", "month"},
        {"terwijl", "while"}, {"vacht", "fur, pelt"}, {"beren", "bears"}, {"sneeuwvlaktes", "snow fields"},
        {"verzamel", "gather, collect"}, {"gejaagd", "hunted"}, {"voorbereidingen", "preparations"} },
},

[5541] = { en = "Ammo for Rumbleshot", tier = 1,
  t = "Munitie voor Rumbleshot",
  d = "Hegnar Rumbleshot verkoopt geweren langs de weg naar Anvilmar. Schutters en mortierteams oefenen veel bij zijn winkel, dus hij heeft altijd nieuwe munitie nodig.$B$BMaar... de laatste kist munitie die ik hem stuurde, is onderweg kwijtgeraakt. Mijn koerier zei dat hij bij de Grizzled Den kampeerde toen de wendigo's hem wegjoegen... en die sukkel heeft de munitie van Rumbleshot laten liggen!$B$B$n, kun jij die munitie halen en naar Rumbleshot brengen? Hij wacht er al op, en hij heeft vast bijna niets meer.",
  o = "Breng Rumbleshot's Ammo naar Hegnar Rumbleshot in Dun Morogh.",
  c = "Geweldig, meer munitie! De lading van de oude Loslor is eindelijk aangekomen! De munitie is laat, maar zoals mijn opa altijd zei: beter laat dan nooit!$B$BHeel erg bedankt, $n. Ik heb al kopers die op deze spullen wachten!",
  p = "Ik hoop dat je niet voor munitie komt, want ik heb bijna niets meer!",
  g = { {"munitie", "ammunition"}, {"verkoopt", "sells"}, {"geweren", "guns, rifles"}, {"schutters", "riflemen, marksmen"},
        {"oefenen", "to practice"}, {"winkel", "shop"}, {"onderweg", "on the way"}, {"wegjoegen", "chased away"},
        {"sukkel", "fool, dope"}, {"laten liggen", "left behind"}, {"lading", "shipment, load"}, {"opa", "grandpa"},
        {"beter laat dan nooit", "better late than never"}, {"kopers", "buyers"} },
},

