[311] = { en = "Return to Marleth", tier = 1,
  t = "Terug naar Marleth",
  d = "Je hebt een vat Scalder van Marleth in de kelder van de stokerij in Kharanos gezet. Nu pak je een vat Thunder Ale als bewijs...",
  o = "Breng het vat Thunder Ale naar Marleth Barleybrew in Brewnall Village.",
  c = "Niet slecht, $n! Was het moeilijk om langs hun bewaker te komen?$B$BMaakt niet uit, heel erg bedankt. En als je ooit stevig bier wilt met een flinke stoot, vergeet de Barleybrews dan niet!",
