[313] = { en = "The Grizzled Den", tier = 1,
  t = "Het grijze hol",
  d = "Een belegeringsmachine besturen is niet voor iedereen. Je hebt een ijzeren greep en stalen zenuwen nodig... gelukkig heb ik allebei! En jij? Hoe zit het met jouw moed? Wil je het me bewijzen?$B$BNou... ik wil mijn machine, Trollplow, wat gezelliger maken. Haal een stapel Wendigo Manes voor me uit de Grizzled Den, ten westen van Kharanos. Die manen zijn een perfect kleed voor het binnendek van Trollplow!",
  o = "Verzamel 8 Wendigo Manes en breng ze naar Pilot Stonegear.",
  c = "Ah ja, deze manen zijn perfect! Je hebt lef, $c. Ik wed dat we nog grote dingen van je gaan zien.",
  p = "Hé, $n. Ben je al bij de Grizzled Den geweest? Die wendigo's kunnen woest zijn.",
  g = { {"hol", "den, lair"}, {"besturen", "to drive, steer"}, {"greep", "grip"}, {"stalen", "steel (adj.)"},
        {"zenuwen", "nerves"}, {"gelukkig", "luckily"}, {"moed", "courage"}, {"bewijzen", "to prove"},
        {"gezelliger", "cozier"}, {"manen", "manes"}, {"kleed", "rug"}, {"lef", "guts, nerve"},
        {"wed", "bet"}, {"woest", "fierce, wild"} },
},

[318] = { en = "Evershine", tier = 1,
  t = "Evershine",
  d = "Rejold Barleybrew experimenteert met zijn bier. Sommige soorten zijn lekker, sommige vies, en sommige... nou, sommige leggen elke dwerg plat, behalve de allersterkste.$B$BHij woont in Brewnall Village, ten westen van Kharanos. Een van zijn drankjes, Evershine, wil ik hebben. Het houdt me warm op de koude weg.$B$BEn... dat spul brandt zo heet dat ik het in de oven van Jetsteam kan gooien voor een extra stoot kracht! Met dat trucje ben ik al vaak uit de problemen gekomen.",
  o = "Haal een vaatje Evershine bij Rejold Barleybrew in Brewnall Village.",
  c = "Heeft Bellowfiz wat van mijn Evershine nodig? Hm... goed dan.",
  g = { {"soorten", "kinds, types"}, {"vies", "gross, nasty"}, {"plat", "flat"}, {"behalve", "except"},
        {"woont", "lives (wonen)"}, {"spul", "stuff"}, {"brandt", "burns"}, {"oven", "furnace, oven"},
        {"gooien", "to throw"}, {"kracht", "power, strength"}, {"trucje", "little trick"}, {"vaatje", "cask, small barrel"} },
},

[319] = { en = "A Favor for Evershine", tier = 1,
  t = "Een gunst voor Evershine",
  d = "Ik heb hier een vaatje Evershine, maar... wil je iets voor me doen? Brewnall Village kan hulp gebruiken tegen de wilde dieren in de sneeuw hier vlakbij. Soms komen ze heel dichtbij.$B$BWe zijn niet bang voor die beren, katten en zwijnen. Geen enkele dwerg met respect voor zichzelf is dat! Maar als jij die dieren voor ons aanpakt, hebben wij meer tijd voor ons handwerk en om bier te brouwen.",
  o = "Dood 6 Ice Claw Bears, 8 Elder Crag Boars en 8 Snow Leopards, en ga dan terug naar Rejold Barleybrew in Brewnall Village.",
  c = "Dank je, $n. Het is fijn om te werken zonder steeds gegrom en gesnuif buiten het dorp te horen.",
  p = "Heb je die wilde dieren aangepakt?",
  g = { {"gunst", "favor"}, {"wilde dieren", "wild animals"}, {"dichtbij", "close"}, {"bang", "afraid"},
        {"katten", "cats"}, {"aanpakt", "deal with (aanpakken)"}, {"handwerk", "craft(s)"},
        {"brouwen", "to brew"}, {"gegrom", "growling"}, {"gesnuif", "snorting"}, {"dorp", "village"} },
},

[320] = { en = "Return to Bellowfiz", tier = 1,
  t = "Terug naar Bellowfiz",
  d = "Hier is je vaatje Evershine, $n. En nogmaals bedankt voor het jagen.",
  o = "Geef het vaatje Evershine aan Pilot Bellowfiz bij Steelgrill's Depot.",
  c = "Ja, dit is precies goed. Ik denk dat ik meteen een fles open om te proeven...",
  p = "Heb je die Evershine?",
  g = { {"meteen", "right away"}, {"fles", "bottle"}, {"open", "open (ik open)"}, {"proeven", "to taste"} },
},

[287] = { en = "Frostmane Hold", tier = 1,
  t = "Frostmane Hold",
  d = "Ik loop achter met mijn verslag, en ik kan je hulp goed gebruiken, $n. Ik heb net ontdekt waar de trollen zich verstoppen. Maar ik zag zo veel trollen dat ik niet naar binnen durfde.$b$bDit is wat ik nodig heb... Ga naar de grot, kijk binnen goed rond, dood een paar trollen en kom dan terug.$b$bNeem de weg naar het noorden uit Kharanos. Bij de brug volg je de bevroren rivier naar het westen tot je bij Iceflow Lake komt. Brewnall Village ligt aan de westkant van het meer. De Hold ligt ten zuidwesten van het dorp.",
  o = "Verken Frostmane Hold en dood 5 Frostmane Headhunters voor Senir Whitebeard in Kharanos.",
  c = "Ah, $n! Ik dacht al dat je de plek makkelijk zou vinden. Mijn uitleg is uitstekend, weet je...$b$bLaat me mijn verslag even afmaken.$b$b<Hij pakt wat papier en krabbelt er snel iets op.>$b$bZo! Nou, haha, dit is wel grappig... Zou je het erg vinden, $n, om nog één laatste gunst voor me te doen?",
  p = "Kun je het niet vinden? Mijn uitleg was heel duidelijk! We hebben niet veel tijd, je moet opschieten! Kom pas terug als je de grot hebt gevonden.",
  e = "Verken Frostmane Hold helemaal",
  g = { {"achter", "behind"}, {"ontdekt", "discovered"}, {"verstoppen", "to hide"}, {"durfde", "dared"},
        {"rond", "around"}, {"brug", "bridge"}, {"rivier", "river"}, {"verken", "explore"},
        {"uitleg", "explanation, directions"}, {"afmaken", "to finish"}, {"krabbelt", "scribbles"},
        {"grappig", "funny"}, {"duidelijk", "clear"}, {"opschieten", "to hurry up"} },
},

[315] = { en = "The Perfect Stout", tier = 1,
  t = "Het perfecte stout",
  d = "Ik ben op zoek, op zoek naar het perfecte stout. Ik weet dat het me lukt: brouwen zit in mijn bloed. Ik moet alleen het juiste recept vinden...$B$BDe Frostmane-trollen kweken een plant, shimmerweed, hoog in de heuvels in het oosten. Ze gebruiken het bij hun vreemde rituelen. Wij dwergen hebben er nog niet veel aan gehad, maar het heeft een bijzondere smaak... en ik wil ermee experimenteren in mijn bier!$B$BHaal shimmerweed bij de Frostmane Seers, of pik het uit de shimmerweed-manden van de trollen.",
  o = "Breng 6 Shimmerweed naar Rejold Barleybrew in Brewnall Village.",
  c = "Geweldig! Ik kan niet wachten om ze in mijn recepten te gebruiken. Er is er één waarin het volgens mij heel goed past...",
  p = "Heb je die shimmerweed? Ik heb bijna een nieuwe lading stout klaar om te brouwen, en ik wil het kruid erbij doen.",
  g = { {"op zoek", "searching, on a quest"}, {"het lukt me", "I'll manage it"}, {"bloed", "blood"},
        {"juiste", "right, correct"}, {"recept", "recipe"}, {"kweken", "to grow, cultivate"}, {"bijzondere", "special, unusual"},
        {"smaak", "taste, flavor"}, {"pik", "swipe, nick (pikken)"}, {"manden", "baskets"}, {"kruid", "herb"} },
},

[432] = { en = "Those Blasted Troggs!", tier = 1,
  t = "Die vervloekte troggs!",
  d = "Die vervloekte troggs maken een puinhoop van mijn werkplek! Kijk nou, daar gaat weer een vat buskruit!$b$bOhhh, ik wil wel naar beneden gaan om al hun magere nekjes om te draaien! Ik wil ze allemaal doden!$b$bAl die stress en woede is vast niet goed voor mijn gezondheid... Wat hebben ze voor mij overgelaten? Niets!$b$bIk zou het zelf doen, maar ik kan niet meer goed mikken! Ga jij de groeve in en dood een paar van die smerige beesten! Ik betaal je! Doe ze pijn, dood ze!",
  o = "Dood 6 Rockjaw Skullthumpers voor Foreman Stonebrow bij de Gol'Bolar-groeve.",
  c = "Nou, nu voel ik me een beetje beter...$b$bMaar ik ben pas blij als ze allemaal dood zijn! Allemaal!",
  p = "Ik word er zo boos van! Grrr...",
  g = { {"puinhoop", "mess, wreck"}, {"werkplek", "work site"}, {"buskruit", "gunpowder"}, {"magere", "skinny"},
        {"om te draaien", "to wring"}, {"woede", "anger"}, {"gezondheid", "health"}, {"overgelaten", "left over"},
        {"mikken", "to aim"}, {"groeve", "quarry"}, {"smerige", "filthy"}, {"pijn", "pain"} },
},

[291] = { en = "The Reports", tier = 1,
  t = "De verslagen",
  d = "Uitstekend! Breng mijn verslag naar Senator Barin Redstone. Hij is een zuurpruim, dus trek je niets aan van zijn humeur. Hij is in Ironforge, in de zaal waar koning Magni hof houdt.$b$bWeet je de weg naar Ironforge niet? Neem de weg naar het noorden uit Kharanos en ga over de brug. Volg dan de weg naar het oosten, de berg op. Er staan grote vaandels langs de weg.$b$bO ja, kun je misschien niet vertellen dat je me geholpen hebt? Ze mogen niet denken dat ik hier niet hard werk, snap je?",
  o = "Breng het verslag van Senir naar Senator Barin Redstone in Ironforge.",
  c = "<Hij leest het verslag snel door.>$b$bIn naam van de KONING!? Is Magni helemaal gek geworden? En die verdraaide Whitebeard... Heeft hij het heft in eigen handen genomen? De Senaat zal hier helemaal niet blij mee zijn, totaal niet.$b$bWat, sta je hier nog? Ga weg, anders roep ik de wachters!",
  p = "Hmm... mijn wachters laten blijkbaar iedereen maar binnen. Nou, wat wil je? Snel een beetje.",
  g = { {"verslagen", "reports"}, {"zuurpruim", "sourpuss"}, {"trek je niets aan van", "don't let ... bother you"},
        {"humeur", "mood, temper"}, {"zaal", "hall"}, {"hof houdt", "holds court"}, {"vaandels", "banners"},
        {"snap je", "you get it?"}, {"gek", "crazy"}, {"het heft in eigen handen", "matters into his own hands"},
        {"wachters", "guards"}, {"blijkbaar", "apparently"} },
},

[412] = { en = "Operation Recombobulation", tier = 1,
  t = "Operatie Recombobulatie",
  d = "Na verder onderzoek van de situatie in Gnomeregan lijkt het erop dat we de troggs niet hebben uitgeroeid. En we hebben ook nog de meeste gnomen veranderd in vreselijke, hersenloze, kwaadaardige lepragnomen.$b$bOzzie en ik willen dat lepra-effect terugdraaien met onze nieuwste uitvinding: de Recombobulator. De machine is bijna klaar, maar we hebben dringend Restabilization Cogs en Gyromechanic Gears nodig. Haal er een paar bij de lepragnomen voor de ingang van Gnomeregan.",
  o = "Breng Razzle Sprysprocket in Kharanos 8 Restabilization Cogs en 8 Gyromechanic Gears.",
  c = "Deze Gyromechanic Gears en Restabilization Cogs passen perfect bij Ozzie's tekeningen voor het Recombobulatie-apparaat. Ik doe nog wat hydrosmeermiddel op de zuigers, stel de krukratel bij en maak de elektrogomgel wat dikker. Dan zijn de gnomen weer zo goed als nieuw.",
  p = "De Recombobulator werkt zodra we genoeg Restabilization Cogs en Gyromechanic Gears hebben.",
  g = { {"onderzoek", "research, analysis"}, {"uitgeroeid", "eradicated"}, {"veranderd", "changed, turned"},
        {"hersenloze", "mindless"}, {"kwaadaardige", "evil, malicious"}, {"terugdraaien", "to reverse"},
        {"uitvinding", "invention"}, {"dringend", "urgently"}, {"ingang", "entrance"}, {"tekeningen", "drawings, schematics"},
        {"apparaat", "device"}, {"zodra", "as soon as"} },
},

[413] = { en = "Shimmer Stout", tier = 1,
  t = "Shimmer Stout",
  d = "Ik wil dat mijn broer Wellart mijn nieuwe Shimmer Stout proeft. Hij is Mountaineer in de zuidelijke wachttoren, een van de twee torens aan de grens met Loch Modan.$B$BHij is geen brouwer zoals wij andere Barleybrews, maar hij houdt van een goed drankje, en ik weet zeker dat hij dit lekker vindt.$B$BWil je dit vat Shimmer Stout naar hem brengen?",
  o = "Breng het vat Shimmer Stout naar Mountaineer Barleybrew.",
  c = "<Mountaineer Barleybrew proeft het Shimmer Stout...>$b$bO. Wauw! Hier gaan je ogen echt van glimmen. Het voelt alsof ik in het donker kan zien!",
  p = "Hallo, $c! Wat brengt jou helemaal hierheen?$b$bIets spannends, hoop ik. Ik heb al dagen niet goed gevochten, en dit vat bier is bijna leeg...",
  g = { {"zuidelijke", "southern"}, {"wachttoren", "guard tower"}, {"grens", "border"}, {"brouwer", "brewer"},
