},

[414] = { en = "Stout to Kadrell", tier = 1,
  t = "Stout voor Kadrell",
  d = "Ik heb nog meer gedronken van het Shimmer Stout dat mijn broer heeft gemaakt. Het is geweldig spul! Ik wil dat een collega-Mountaineer het ook proeft. Hij heet Kadrell, en hij patrouilleert meestal op de weg door Thelsamar in Loch Modan.$B$BOm in Thelsamar te komen, ga je naar het zuidoosten door de tunnel. Waar het pad zich splitst, ga je naar het noordoosten de weg op. Volg die weg recht naar Thelsamar.$B$BGeef Mountaineer Kadrell dit vaatje Shimmer Stout en vraag wat hij ervan vindt!",
  o = "Breng het vaatje Shimmer Stout naar Mountaineer Kadrell.",
  c = "Zo, laat me eens proeven...$b$bBij Magni's baard! Hier word je duizelig van! En je armen en benen worden er licht van.$b$bHet voelt alsof ik kan vliegen!",
  p = "Gegroet, $c, en welkom in Thelsamar!",
  g = { {"gedronken", "drunk (past participle)"}, {"collega", "colleague, fellow"}, {"patrouilleert", "patrols"},
        {"meestal", "usually"}, {"pad", "path"}, {"splitst", "forks, splits"}, {"vraag", "ask"},
        {"duizelig", "dizzy"}, {"benen", "legs"}, {"licht", "light"}, {"vliegen", "to fly"} },
},

[415] = { en = "Rejold's New Brew", tier = 1,
  t = "Het nieuwe bier van Rejold",
  d = "Rejold Barleybrew in Brewnall Village vraagt naar jou.$B$BHij wil met je praten over een nieuw drankje dat hij aan het brouwen is. Hij zei iets over dat jij hem ermee hebt geholpen. Ga misschien even terug naar Brewnall Village om te horen wat hij te zeggen heeft.$B$BEr zit misschien wel gratis drank voor je in...",
  o = "Praat met Rejold Barleybrew.",
  c = "$n! Weet je nog, die shimmerweed die je me bracht? Nou, ik heb het in een paar recepten gebruikt, en een ervan is heel goed gelukt!$b$bHier, proef maar en zeg wat je ervan vindt...",
  g = { {"vraagt naar", "is asking for"}, {"aan het brouwen", "brewing (in progress)"}, {"gratis", "free"},
        {"weet je nog", "do you remember"}, {"gelukt", "turned out well, succeeded"} },
},

[419] = { en = "The Lost Pilot", tier = 1,
  t = "De verdwaalde piloot",
  d = "Mijn vriend en collega-piloot Mori Hildelve is verdwaald in de heuvels. We zochten een zeldzaam erts dat nodig is voor sterk buskruit. Tijdens het zoeken reed hij met zijn machine een steile heuvel op, en toen ging hij kapot!$B$BHildelve was nog steeds zeker dat het erts in deze bergen lag. Hij liet mij onze machines bewaken en ging te voet verder zoeken.$B$BHet is nu al dagen geleden, en 's nachts hoor ik enge brullende geluiden in de heuvels. Mori is zo taai als een spijker, maar ik maak me zorgen.$B$BAlsjeblieft, $n. Vind hem.",
  o = "Vind Pilot Hildelve.",
  c = "Hier ligt het lichaam van een dwerg: verscheurd, bevroren en kaal gepikt door aaseters uit de bergen. In zijn hand houdt hij een boek met de snel neergekrabbelde notities van Mori Hildelve. En om zijn lijf zit, nog in uitstekende staat, een Brigadier's Vest.$b$bHier is de piloot van de belegeringsmachine dus aan zijn einde gekomen.",
  g = { {"verdwaalde", "lost"}, {"zeldzaam", "rare"}, {"erts", "ore"}, {"steile", "steep"}, {"te voet", "on foot"},
        {"brullende", "roaring"}, {"geluiden", "sounds"}, {"zo taai als een spijker", "tough as nails"},
        {"lichaam", "body"}, {"verscheurd", "mauled, torn"}, {"aaseters", "scavengers"}, {"notities", "notes"},
        {"lijf", "body (informal)"}, {"staat", "condition, state"}, {"einde", "end"} },
},

[417] = { en = "A Pilot's Revenge", tier = 1,
  t = "De wraak van een piloot",
  d = "Hildelve schreef in zijn dagboek dat hij werd aangevallen door Mangeclaw, een 'enorme Ice Claw-beer'. Hij joeg het beest weg, maar pas nadat het hem zwaar had verwond.$B$BAls je ziet hoe het lichaam van Hildelve eruitziet, moet Mangeclaw later zijn teruggekomen om hem te doden.$B$BMaar Hildelve schreef in zijn dagboek één laatste wens:$B$BWraak op Mangeclaw.",
  o = "Dood Mangeclaw.$B$BBreng zijn Mangy Claw en Hildelve's Journal naar Pilot Hammerfoot.",
  c = "Dit is triest nieuws, want Hildelve was een goede vriend. Ik wou dat ik erbij was geweest toen je dat beest, Mangeclaw, vond!$b$bDank je wel, $n. De piloten van de Ironforge Siege Brigade zullen nooit vergeten wat je gedaan hebt.",
  p = "Hallo, $n. Heb je nieuws over mijn vriend Hildelve?",
  g = { {"wraak", "revenge"}, {"schreef", "wrote"}, {"enorme", "huge"}, {"joeg ... weg", "drove off (wegjagen)"},
        {"pas nadat", "only after"}, {"verwond", "wounded"}, {"wens", "wish"}, {"triest", "sad, grim"},
        {"ik wou dat", "I wish that"} },
},

[433] = { en = "The Public Servant", tier = 1,
  t = "De dienaar van het volk",
  d = "Ik ben lid van de Senaat en van de Explorers' League. Daarom heb ik besloten om dit deel van de troggplaag in ons land zelf aan te pakken.$b$bZe hebben van de Gol'Bolar-groeve een enorme puinhoop gemaakt, en zonder reden. Toen we diep in de aarde groeven, kwamen ze naar buiten. Ze hebben onze machines kapotgemaakt en de mijnwerkers weggejaagd. We kunnen niet veel anders doen dan ze allemaal uitroeien, alles herbouwen en dan weer aan het werk gaan.$b$bAls je me helpt met de troggs, betaal ik je graag voor je tijd.",
  o = "Dood 10 Rockjaw Bonesnappers voor Senator Mehr Stonehallow bij de Gol'Bolar-groeve.",
  c = "Het is een begin. Hopelijk kunnen we er gebruik van maken en Mountaineers sturen om het gebied te beveiligen. Dan kunnen we beginnen met het herstel en kunnen de mijnwerkers weer aan het werk.$b$bBedankt voor je hulp, $n.",
  p = "Als we de troggs uit de Gol'Bolar-groeve kunnen verdrijven, is dat de eerste van vele stappen om van deze plaag af te komen.",
  g = { {"dienaar", "servant"}, {"volk", "people, nation"}, {"lid", "member"}, {"besloten", "decided"},
        {"plaag", "plague, infestation"}, {"reden", "reason"}, {"aarde", "earth"}, {"groeven", "dug (graven)"},
        {"mijnwerkers", "miners"}, {"uitroeien", "to exterminate"}, {"herbouwen", "to rebuild"}, {"hopelijk", "hopefully"},
        {"gebied", "area"}, {"beveiligen", "to secure"}, {"herstel", "restoration, repair"}, {"stappen", "steps"} },
},

[312] = { en = "Tundra MacGrann's Stolen Stash", tier = 1,
  t = "De gestolen voorraad van Tundra MacGrann",
  d = "Ik had gedroogd vlees voor een hele maand. Ik had het gezouten en weggesloten voor de koude tijd. Ik deed het op slot, zodat de beren er niet bij konden! Maar terwijl ik op herten aan het jagen was, is dat beest, Old Icebeard, ervandoor gegaan met mijn vleeskast. Hij krijgt dat thorium niet kapot. Maar ik verhonger als ik mijn vlees niet terugkrijg.$b$bJij lijkt wat stiller dan ik. Misschien kun jij mijn voorraad terughalen? Met dit slechte been kom ik die grot nooit snel genoeg in en uit.",
  o = "Haal het gedroogde vlees van Tundra MacGrann uit de gestolen vleeskast in de grot van Old Icebeard.",
  c = "Wat ben jij een goed mens, $n! Dankzij jouw moed ga ik niet verhongeren als de sneeuwbuien van de koude tijd komen.",
  p = "Ben je in mijn vleeskast gekomen, $n?",
  g = { {"gedroogd", "dried"}, {"gezouten", "salted"}, {"weggesloten", "locked away"}, {"op slot", "locked"},
        {"herten", "deer"}, {"ervandoor gegaan", "made off, ran away"}, {"vleeskast", "meat locker"},
        {"verhonger", "starve"}, {"stiller", "quieter, stealthier"}, {"been", "leg"}, {"dankzij", "thanks to"},
        {"sneeuwbuien", "snow flurries"} },
},

[314] = { en = "Protecting the Herd", tier = 1,
  t = "De kudde beschermen",
  d = "Midden in de nacht hoorden we geschreeuw. En vanochtend, ja hoor, misten er twee rammen uit de kudde. Dat gemene beest Vagash jaagt op ons levensonderhoud. Het grootste deel van het leger van koning Magni vecht ver weg met de Alliance. Er is niemand om Vagash tegen te houden.$b$bMisschien ben jij dapper genoeg om het beest te zoeken en te doden. Breng me een van zijn hoektanden, dan beloon ik je. Vagash zit net boven de boerderij hier, maar pas op: hij is dodelijk.",
  o = "Rudra Amberstill wil dat je Vagash doodt en zijn hoektand naar haar brengt bij de Ram-boerderij.",
  c = "Heel goed gedaan! Veron zal zo blij zijn als hij het goede nieuws hoort. Vagash doden is geen makkelijke taak. Ik denk dat jij op een dag samen met de mannen van koning Magni zult vechten aan het front van de Alliance.",
  p = "Vagash maakt de kudde nog steeds bang! Help ons alsjeblieft en dood dat afschuwelijke beest.",
  g = { {"beschermen", "to protect"}, {"geschreeuw", "cries, screaming"}, {"vanochtend", "this morning"},
        {"misten", "were missing"}, {"gemene", "nasty, mean"}, {"levensonderhoud", "livelihood"}, {"vecht", "fights"},
        {"dapper", "brave"}, {"hoektanden", "fangs"}, {"hoektand", "fang"}, {"beloon", "reward"},
        {"boerderij", "farm, ranch"}, {"dodelijk", "deadly"}, {"front", "front (war)"}, {"afschuwelijke", "horrible, wretched"} },
},

-- Dun Morogh follow-ups for later levels (tier 2: A2)
[466] = { en = "Search for Incendicite", tier = 2,
  t = "Op zoek naar incendiciet",
  d = "Ik heb gehoord dat er een zeldzaam erts, incendiciet, is gevonden in de Wetlands, in een grot ten noordwesten van Algaz Gate. Incendiciet is instabiel spul, en het is moeilijk te gebruiken zonder jezelf op te blazen. Maar ik weet zeker dat je er, als je het op de juiste manier smelt, granaten van kunt maken die een flinke klap uitdelen!$B$BHaal incendiciet-erts voor me, dan zoek ik iemand die moedig genoeg is om ermee te experimenteren.$B$BO, en om het erts uit een ader te halen, moet je kunnen mijnen. Kun je dat niet? Neem dan een vriend mee naar die grot die het wel kan!",
  o = "Breng 6 Incendicite Ore naar Pilot Stonegear in Dun Morogh.",
  c = "Je hebt het erts! Goed gedaan, $n! Ik laat er meteen iemand mee aan de slag gaan. Laten we hopen dat hij zichzelf niet opblaast!",
  p = "Waar blijft dat erts, $n?!",
  g = { {"instabiel", "unstable, volatile"}, {"opblazen", "to blow up"}, {"op de juiste manier", "the right way"},
        {"smelt", "smelt (smelten)"}, {"granaten", "shells, grenades"}, {"klap", "blow, punch"},
        {"moedig", "brave"}, {"ader", "vein (of ore)"}, {"mijnen", "to mine"}, {"aan de slag gaan", "get to work"} },
},

[467] = { en = "Stonegear's Search", tier = 2,
  t = "De zoektocht van Stonegear",
  d = "Pilot Stonegear is dol op zijn belegeringsmachine, zoals elke piloot hoort te zijn! En hij zoekt altijd naar nieuwe manieren om zijn tank sterker te maken!$B$BHij heeft geruchten gehoord over een zeldzaam erts, en hij zoekt iemand die het voor hem wil opsporen. Als je zin hebt in avontuur, ga dan naar Stonegear bij Steelgrill's Depot in Dun Morogh en vraag wat hij wil.",
  o = "Praat met Pilot Stonegear.",
  c = "Hallo, $n. Je komt voor de opdracht die ik heb, hè? Fijn om een jonge $r te zien die staat te popelen voor avontuur!",
  g = { {"is dol op", "loves, is crazy about"}, {"hoort te zijn", "ought to be"}, {"manieren", "ways"},
        {"geruchten", "rumors"}, {"opsporen", "to track down"}, {"zin hebben in", "to feel like"},
